_run_id = None
try:
    from pipeline_registry import run_start, run_complete, run_fail
    _run_id = run_start('finviz_screener_runner')
except Exception:
    pass
try:
    dry = '--dry-run' in sys.argv
    sid = None
    if '--screener' in sys.argv:
        sid = sys.argv[sys.argv.index('--screener') + 1]
    result = run_screener(screener_id=sid, dry_run=dry)
    if '--json' in sys.argv:
        print(json.dumps(result, indent=2, default=str))
    else:
        for r in result.get('results', []):
            if r['new_tickers'] > 0:
                print(f"  {r['screener_id']:>25}: {r['total_found']} found, {r['new_tickers']} NEW → {r['sample'][:5]}")
    try:
        if _run_id:
            total_new = sum((r.get('new_tickers', 0) for r in result.get('results', [])))
            run_complete(_run_id, rows_processed=total_new)
    except Exception:
        pass
except Exception as _e:
    try:
        if _run_id:
            run_fail(_run_id, str(_e))
    except Exception:
        pass
    raise

feedback_loop_processor.main:
def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description='Feedback Loop Processor')
    parser.add_argument('--dry-run', action='store_true', help='SELECT and count only (READ ONLY session); no write, no receipt')
    args = parser.parse_args(argv)
    started = datetime.now().astimezone().isoformat()
    print(f'[feedback_loop] Starting — {datetime.now().isoformat()}')
    counts: dict = {}
    conn = None
    try:
        conn = _get_conn()
        if args.dry_run:
            _receipt_lib().enforce_readonly(conn)
        for key, label, fn in STEPS:
            counts[key] = fn(conn, dry_run=args.dry_run)
            print(f"  {label}{(' (would)' if args.dry_run else '')}: {counts[key]}")
    except Exception as exc:
        print(f'[feedback_loop] FAILED: {type(exc).__name__}: {exc}')
        if args.dry_run:
            _receipt_lib().dry_run_report(LANE_ID, {**counts, 'error': type(exc).__name__, 'exit_would_be': 1}, would_write=WOULD_WRITE)
            return 1
        _receipt_lib().write_lane_receipt(LANE_ID, ok=False, exit_code=1, started_at=started, script='feedback_loop_processor.py', summary=counts, error=f'{type(exc).__name__}: {exc}')
        raise
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    if args.dry_run:
        _receipt_lib().dry_run_report(LANE_ID, counts, would_write=WOULD_WRITE)
        print(f'[feedback_loop] DRY-RUN complete — {datetime.now().isoformat()}')
        return 0
    _receipt_lib().write_lane_receipt(LANE_ID, ok=True, exit_code=0, started_at=started, script='feedback_loop_processor.py', summary=counts)
    print(f'[feedback_loop] Complete — {datetime.now().isoformat()}')
    return 0

research_watchlist_discovery.main:
def main(argv=None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument('--dry-run', action='store_true', help='read + report only; wins over --apply')
    ap.add_argument('--apply', action='store_true')
    ap.add_argument('--max-symbols', type=int, default=60)
    args = ap.parse_args(argv)
    if args.dry_run or not args.apply:
        return _dry_run(args)
    lr = _receipt_lib()
    started = datetime.now(timezone.utc).isoformat()
    try:
        conn = _get_conn()
        by_symbol = _collect(conn, args.max_symbols)
        written = refreshed = failed = 0
        for sym, cand in by_symbol.items():
            try:
                outcome = _upsert(conn, cand)
                if outcome == 'inserted':
                    written += 1
                elif outcome == 'refreshed':
                    refreshed += 1
            except Exception as e:
                conn.rollback()
                failed += 1
                print(f'  [research-discovery] {sym} upsert error: {e}')
            else:
                conn.commit()
        ok, rows, error = run_report(len(by_symbol), written, refreshed)
        try:
            from lib.data_source_report import report_source
            report_source(SOURCE_KEY, ok, rows=rows, error=error)
        except Exception:
            pass
        print(f'[research-discovery] wrote {written} new research ideas, refreshed {refreshed} already listed, {failed} failed')
        conn.close()
    except Exception as exc:
        lr.write_lane_receipt(LANE_ID, ok=False, exit_code=1, started_at=started, script='research_watchlist_discovery.py', error=f'{type(exc).__name__}: {exc}')
        raise
    rc = 1 if by_symbol and failed == len(by_symbol) else 0
    lr.write_lane_receipt(LANE_ID, ok=rc == 0, exit_code=rc, started_at=started, script='research_watchlist_discovery.py', summary={'candidates': len(by_symbol), 'written': written, 'refreshed': refreshed, 'failed': failed})
    return rc

resolve_due_checkpoints.main:
def main() -> int:
    ap = argparse.ArgumentParser(description='Resolve due outcome checkpoints')
    ap.add_argument('--apply', action='store_true', help='write SCHEDULED resolutions (default: dry run)')
    ap.add_argument('--apply-pending-data', action='store_true', help=f'resolve obtainable / expire never-resolvable PENDING_DATA (requires {PENDING_APPLY_ENV}=1; append-only)')
    ap.add_argument('--json', action='store_true')
    ap.add_argument('--migrate-missing-deadlines', action='store_true', help='preview conservative deadline migration; --apply appends proposals only')
    ap.add_argument('--limit', type=int, default=None)
    ap.add_argument('--as-of', default=None, help="Pin PENDING_DATA triage/apply clock (ISO date or datetime). Use when today's ticker_prices row is a known copy-forward and a prior session close is the honest horizon.")
    args = ap.parse_args()
    if args.migrate_missing_deadlines:
        root = _state_root()
        rows = checkpoint_deadline_migrations(_jsonl(root / CHECKPOINT_PATH), limit=args.limit)
        if args.apply:
            for row in rows:
                _append(root / CHECKPOINT_PATH, row)
        print(json.dumps({'schema': 'CheckpointDeadlineMigration@v1', 'applied': args.apply, 'proposed': len(rows), 'derived': sum((bool(r.get('due_at')) for r in rows)), 'review_required': sum((not r.get('due_at') for r in rows)), 'authority': 'READ_ONLY_ADVISORY', 'samples': rows[:5]}, default=str))
        return 0
    result = run(apply=args.apply, limit=args.limit, apply_pending_data=args.apply_pending_data, now=_parse_as_of(args.as_of))
    if args.json:
        print(json.dumps(result, indent=2, sort_keys=True, default=str))
    else:
        print('── SCHEDULED due ──')
        for key in ('due', 'resolved', 'pending_data', 'not_price_resolvable', 'applied'):
            print(f'{key:22} {result[key]}')
        for reason, n in sorted(result['not_resolvable_reasons'].items(), key=lambda kv: -kv[1]):
            print(f'  not resolvable: {n:3}x  {reason}')
        for s in result['samples']:
            rec = str(s.get('recommendation') or '')
            if len(rec) > 24:
                rec = rec[:21] + '...'
            print(f"  {s['symbol'] or '?':6} {rec:24} {s['change_pct']:+.2f}%  -> {s['outcome_id']}")
        triage = result['pending_triage']
        print('── PENDING_DATA triage ──')
        print(f"{'as_of':22} {triage['as_of']}")
        print(f"{'root':22} {triage['root']}")
        for key in ('pending_total', 'future_dated', 'obtainable', 'stuck_waiting_data', 'never_resolvable', 'applied', 'resolved', 'expired'):
            print(f'{key:22} {triage[key]}')
        if triage.get('apply_refused'):
            refused = triage['apply_refused']
            print(f"  APPLY_REFUSED: {refused.get('detail')}")
        for reason, n in sorted(triage['reasons'].items(), key=lambda kv: -kv[1]):
            print(f'  pending reason: {n:3}x  {reason}')
        for s in triage['resolve_samples']:
            print(f"  would-resolve {s.get('symbol') or '?':6} {s.get('change_pct'):+.2f}%  {s.get('decision_price_date')}→{s.get('horizon_price_date')}  cid={s.get('checkpoint_id')}")
        for s in triage['expire_samples']:
            print(f"  would-expire  {s.get('symbol') or '?':6} {s.get('reason')}  cid={s.get('checkpoint_id')}")
    return 0
